// Implementor
interface Appliance {
    boolean isRunning();
    void turnOn();
    void turnOff();
    int getIntensity();
    void setIntensity(int level);
}

// ConcreteImplementor: AC
class AC implements Appliance {
    private boolean running = false;
    private int intensity = 5;

    @Override
    public boolean isRunning() { return running; }

    @Override
    public void turnOn() {
        running = true;
        System.out.println("AC: Turned ON");
    }

    @Override
    public void turnOff() {
        running = false;
        System.out.println("AC: Turned OFF");
    }

    @Override
    public int getIntensity() { return intensity; }

    @Override
